$ErrorActionPreference = 'Stop'

# Read the SDK path generated by Flutter instead of hardcoding a Windows username.
$taskWorkspace = Split-Path -Parent $PSScriptRoot
$taskProperties = Join-Path $taskWorkspace 'android/local.properties'
$taskSdkPath = $env:ANDROID_HOME
if (Test-Path -LiteralPath $taskProperties) {
    $taskSdkLine = Get-Content -LiteralPath $taskProperties | Where-Object { $_ -match '^sdk\.dir=' } | Select-Object -First 1
    if ($taskSdkLine) {
        $taskSdkPath = ($taskSdkLine -replace '^sdk\.dir=', '').Replace('\\', '\').Replace('\:', ':')
    }
}
if (-not $taskSdkPath) { throw 'Android SDK not found. Run flutter doctor first.' }
$taskAdb = Join-Path $taskSdkPath 'platform-tools/adb.exe'
if (-not (Test-Path -LiteralPath $taskAdb)) { throw "ADB not found: $taskAdb" }

$taskDevicesOutput = & $taskAdb devices
if ($LASTEXITCODE -ne 0) { throw 'Unable to list Android devices.' }
$taskDeviceIds = @($taskDevicesOutput | ForEach-Object {
    if ($_ -match '^(\S+)\s+device$') { $Matches[1] }
})
if ($taskDeviceIds.Count -eq 0) { throw 'Connect an Android device with USB debugging enabled, or start an emulator.' }

foreach ($taskDeviceId in $taskDeviceIds) {
    & $taskAdb -s $taskDeviceId reverse tcp:5080 tcp:5080
    if ($LASTEXITCODE -ne 0) { throw "Unable to forward port 5080 for $taskDeviceId." }
    Write-Host "${taskDeviceId}: Android localhost:5080 -> backend localhost:5080"
}
